export interface Axis {
    x: number;
    y: number;
}
export type Mode = 'x' | 'y' | 'z';
export interface Modes {
    mode: Mode;
    radius: Axis;
}
export interface Props {
    angle: number;
    className?: string;
    mode: Mode;
    readonly?: boolean;
    onRotateStart?: () => void;
    onRotate?: (angle: number) => void;
    onRotateEnd?: () => void;
}
